import base64, json, shutil
from pathlib import Path
from datetime import datetime

ROOT=Path(__file__).resolve().parent
BACKUP=ROOT/f"backup_before_travelshield_v3_{datetime.now():%Y%m%d_%H%M%S}"
PAYLOAD=json.loads(r'''{"workspace/forms.py": "", "templates/base.html": "", "templates/public/landing.html": "", "templates/workspace/home.html": "", "templates/workspace/form.html": "", "templates/workspace/detail.html": "", "templates/workspace/history.html": "", "static/app.css": ""}''')
for rel in PAYLOAD:
    src=ROOT/rel
    if src.exists():
        dst=BACKUP/rel; dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,dst)
for rel,data in PAYLOAD.items():
    dst=ROOT/rel; dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(base64.b64decode(data))
print("="*62)
print("TRAVELSHIELD V3 FRONTEND REPAIR COMPLETE")
print("="*62)
print("Backup:",BACKUP)
print("Updated: landing, dashboard, assessment form, result, history, CSS")
print("Next: python manage.py check && python manage.py runserver")
